from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY", Resolution.Minute, Market.USA,
            fillForward=True, leverage=1, extendedMarketHours=False
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-100, 100)
                       .Expiration(timedelta(0), timedelta(days=370))
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy, self.consolidator
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        if bar.End.date() < self.StartDate.date():
            return

        if self.fast.IsReady:
            self.previous_fast = self.fast.Current.Value
        if self.slow.IsReady:
            self.previous_slow = self.slow.Current.Value

        self.fast.Update(bar.End, bar.Close)
        self.slow.Update(bar.End, bar.Close)

        if not time(9, 45) <= bar.End.time() <= time(14, 30):
            return

        if not (
            self.fast.IsReady and self.slow.IsReady
            and self.previous_fast is not None
            and self.previous_slow is not None
        ):
            return

        bullish = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish:
            self.TryEnter()

    def TryEnter(self):
        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        if self.no_entry_date == self.Time.date():
            return

        chain = self.CurrentSlice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        today = self.Time.date()
        valid_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= today + timedelta(days=7)
        })

        if not valid_expirations:
            self.Debug("Skipped entry: no valid expiration")
            return

        expiration = valid_expirations[0]
        spy_price = self.Securities[self.spy].Price
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call")
            return

        selected = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.held_symbol = selected.Symbol
        self.expiration = expiration
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            self.held_symbol, 1, False,
            "Bullish five-minute crossover"
        )

        self.Debug("Entry submitted: " + str(self.held_symbol))

    def OnData(self, slice):
        if self.held_symbol is None:
            return

        if self.expiration is not None:
            previous_trading_day = self.GetPreviousTradingDay(self.expiration)

            if self.Time.date() == previous_trading_day:
                if self.Time.time() >= time(15, 45):
                    self.SubmitExit("Expiration time stop")
                return

            if self.Time.date() >= self.expiration:
                self.no_entry_date = self.Time.date()
                self.SubmitExit("Expiration cleanup")
                return

        if self.entry_price is None or self.exit_ticket is not None:
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol, -quantity, False, reason
        )
        self.Debug("Exit submitted: " + reason)

    def GetPreviousTradingDay(self, date):
        previous = date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(previous):
            previous -= timedelta(days=1)

        return previous

    def OnOrderEvent(self, event):
        if self.entry_ticket is not None:
            if event.OrderId == self.entry_ticket.OrderId:
                if event.Status == OrderStatus.Filled:
                    self.entry_price = event.FillPrice
                    self.Debug("Entry filled: " + str(self.entry_price))

                elif event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.held_symbol = None
                    self.expiration = None
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if event.OrderId == self.exit_ticket.OrderId:
                if event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled: " + str(event.FillPrice))
                    self.held_symbol = None
                    self.entry_price = None
                    self.expiration = None
                    self.entry_ticket = None
                    self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            "Unexpected exercise or assignment: liquidating SPY equity"
        )

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy, -quantity, False,
                "Unexpected assignment cleanup"
            )
